<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref } from 'vue'
import { request } from '@/api/client'
import {RouterLink} from 'vue-router'
import {authStore} from '@/stores/auth'
import type { WorkspaceView } from '@/types/api'
const props=defineProps<{group:WorkspaceView;owner:boolean;manager:boolean}>(), emit=defineEmits<{refresh:[];state:[{archived:boolean;dissolved:boolean;acceptRequests:boolean}]}>()
const state=ref<{archived:boolean;dissolved:boolean;acceptRequests:boolean}>(), pending=ref<{id:string;kind:string;displayName:string;identityCode:string}[]>([]), reports=ref<{id:string;messageId:string;reason:string;status:string;displayName:string}[]>([]),target=ref(''),password=ref(''),name=ref(''),busy=ref(false),error=ref('')
let active=true;onBeforeUnmount(()=>{active=false;password.value=''})
const base=`/workspaces/${props.group.id}`
async function load(){try{const s=await request<typeof state.value>(base+'/lifecycle');if(!active)return;state.value=s;if(s)emit('state',s);if(props.manager){const [p,r]=await Promise.all([request<typeof pending.value>(base+'/invitations'),request<typeof reports.value>(base+'/reports')]);if(active){pending.value=p;reports.value=r}}}catch(e){if(active)error.value=(e as Error).message}}
onMounted(load)
async function run(path:string,body:unknown,method='POST'){if(busy.value)return;busy.value=true;error.value='';try{await request(path,{method,body:JSON.stringify(body)});if(active){password.value='';await load();emit('refresh')}}catch(e){if(active)error.value=(e as Error).message}finally{if(active)busy.value=false}}
</script>
<template><section class="lifecycle"><p v-if="state?.archived" role="status">{{state.dissolved?'群组已解散，群主可查阅历史。':'群组已归档，暂不能发送新消息。'}}</p><details v-if="owner||manager"><summary>群组管理 · #{{group.id}}</summary><p v-if="error" class="form-error" role="alert">{{error}}</p>
 <div v-if="owner&&state&&!state.dissolved" class="lifecycle-options"><button class="button button--ghost button--small" :disabled="busy" @click="run(base+'/lifecycle',{archived:!state.archived,acceptRequests:state.acceptRequests},'PUT')">{{state.archived?'恢复群组':'归档群组'}}</button><label><input :checked="state.acceptRequests" type="checkbox" :disabled="busy||state.archived" @change="run(base+'/lifecycle',{archived:false,acceptRequests:!state.acceptRequests},'PUT')" />允许通过群组编号申请加入</label></div>
 <section v-if="pending.length"><h4>待处理申请与邀请</h4><div v-for="p in pending" :key="p.id" class="request-row"><div>{{p.displayName}}<small>{{p.identityCode}} · {{p.kind==='REQUEST'?'申请加入':'邀请待确认'}}</small></div><template v-if="p.kind==='REQUEST'"><button class="table-action" :disabled="busy" @click="run('/workspaces/invitations/'+p.id+'/decision',{accept:true})">同意</button><button class="table-action" :disabled="busy" @click="run('/workspaces/invitations/'+p.id+'/decision',{accept:false})">拒绝</button></template></div></section>
 <section v-if="reports.length"><h4>消息举报</h4><div v-for="r in reports" :key="r.id" class="request-row"><div>{{r.reason}}<small>{{r.displayName}} · {{r.status}}</small></div><template v-if="r.status==='OPEN'"><button class="table-action" :disabled="busy" @click="run(base+'/messages/'+r.messageId+'/recall',{})">撤回消息</button><RouterLink v-if="authStore.has('moderation:review')" to="/app/moderation">前往平台审核</RouterLink><small v-else>等待平台审核</small></template></div></section>
 <details v-if="owner&&state&&!state.dissolved"><summary>转让与解散</summary><label class="field-label">新群主<select v-model="target" class="field-input"><option value="">选择现有成员</option><option v-for="m in group.members.filter(m=>m.userId!==group.ownerId)" :key="m.userId" :value="String(m.userId)">{{m.displayName}} · @{{m.username}}</option></select></label><label class="field-label">确认当前密码<input v-model="password" class="field-input" type="password" autocomplete="current-password" :disabled="busy" /></label><button class="button button--ghost" :disabled="busy||!target||!password||state.archived" @click="run(base+'/transfer',{targetId:Number(target),password})">转让群主</button><label class="field-label">解散前输入群组全名<input v-model="name" class="field-input" :placeholder="group.name" /></label><p>解散后成员失去访问权，群主保留只读历史。此操作不能撤销。</p><button class="button button--ghost" :disabled="busy||!password||name!==group.name" @click="run(base+'/dissolve',{name,password})">确认解散</button></details>
 </details></section></template>
<style scoped>.lifecycle{border-bottom:1px solid var(--line);padding:12px 0;font-size:13px}summary{cursor:pointer;color:var(--green);padding:8px 0}small{display:block;color:var(--muted);font-size:11px}.request-row{display:flex;gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line)}.request-row>div{flex:1}.lifecycle-options{display:flex;gap:20px;align-items:center;padding:16px 0}.field-label{margin:16px 0}</style>
